84	export function isTaskPastDue(
85	  dateStr?: string | Date | null,
86	  referenceDate: string = getSystemReferenceDate()
87	): boolean {
88	  if (!dateStr) return false;
89	  let clean: string;
90	  if (typeof dateStr === "string") {
91	    clean = dateStr.length > 10 ? dateStr.slice(0, 10) : dateStr;
92	  } else if (dateStr instanceof Date) {
93	    if (isNaN(dateStr.getTime())) return false;
94	    clean = new Intl.DateTimeFormat("en-CA", {
95	      timeZone: "Asia/Ho_Chi_Minh",
96	      year: "numeric",
97	      month: "2-digit",
98	      day: "2-digit",
99	    }).format(dateStr);
100	  } else {
101	    return false;
102	  }
103	  const cleanRef =
104	    typeof referenceDate === "string" && referenceDate.length > 10
105	      ? referenceDate.slice(0, 10)
106	      : String(referenceDate);
107	  return clean < cleanRef;
108	}
