112	 * Một nhiệm vụ bị xem là quá hạn nếu:
113	 * 1. Không ở trạng thái kết thúc (COMPLETED, CANCELLED).
114	 * 2. Trạng thái bản ghi là OVERDUE HOẶC hạn chót (dueDate) trước ngày tham chiếu hệ thống.
115	 */
116	export function isTaskOverdue(
117	  status: string,
118	  dueDate?: string | Date | null,
119	  referenceDate: string = getSystemReferenceDate()
120	): boolean {
121	  const s = (status || "").toUpperCase();
122	  const isCompletedOrCancelled = s === "COMPLETED" || s === "CANCELLED";
123	  if (isCompletedOrCancelled) return false;
124	  return s === "OVERDUE" || isTaskPastDue(dueDate, referenceDate);
125	}
