132	export function parseDateParts(dateInput: unknown): { year: number; month: number; day: number } | null {
133	  if (!dateInput) return null;
134	  if (typeof dateInput === "string") {
135	    const trimmed = dateInput.trim();
136	    if (!trimmed) return null;
137	    const match = trimmed.match(/^(\d{4})-(\d{2})-(\d{2})/);
138	    if (match) {
139	      return {
140	        year: parseInt(match[1], 10),
141	        month: parseInt(match[2], 10),
142	        day: parseInt(match[3], 10),
143	      };
144	    }
145	    const d = new Date(trimmed);
146	    if (isNaN(d.getTime())) return null;
147	    return parseDateParts(d);
148	  }
149	  if (dateInput instanceof Date) {
150	    if (isNaN(dateInput.getTime())) return null;
151	    const formatter = new Intl.DateTimeFormat("en-CA", {
152	      timeZone: "Asia/Ho_Chi_Minh",
153	      year: "numeric",
154	      month: "2-digit",
155	      day: "2-digit",
156	    });
157	    const parts = formatter.formatToParts(dateInput);
158	    const y = parts.find((p) => p.type === "year")?.value;
159	    const m = parts.find((p) => p.type === "month")?.value;
160	    const d = parts.find((p) => p.type === "day")?.value;
161	    if (!y || !m || !d) return null;
162	    return {
163	      year: parseInt(y, 10),
164	      month: parseInt(m, 10),
165	      day: parseInt(d, 10),
166	    };
167	  }
168	  return null;
169	}
