171	function buildAcademicMonthPeriod(
172	  calendarYearForMonth: number,
173	  namedMonth: number,
174	  academicYear?: string
175	): AcademicMonthPeriod {
176	  const prevYear = namedMonth === 1 ? calendarYearForMonth - 1 : calendarYearForMonth;
177	  const prevMonth = namedMonth === 1 ? 12 : namedMonth - 1;
178	  const startDate = `${prevYear}-${pad(prevMonth)}-25`;
179	  const endDate = `${calendarYearForMonth}-${pad(namedMonth)}-24`;
180	  const shortDateSpan = `25/${pad(prevMonth)} - 24/${pad(namedMonth)}`;
181	  const label = `Tháng ${namedMonth}`;
182	  const fullLabel = `Tháng ${namedMonth} / ${calendarYearForMonth} (${shortDateSpan})`;
183	  const monthIndexInYear = namedMonth >= 9 ? namedMonth - 9 : namedMonth + 3;
184	  const derivedAcademicYear =
185	    academicYear ??
186	    (namedMonth >= 9
187	      ? `${calendarYearForMonth}-${calendarYearForMonth + 1}`
188	      : `${calendarYearForMonth - 1}-${calendarYearForMonth}`);
189	
190	  return {
191	    monthNumber: namedMonth,
192	    monthIndexInYear,
193	    academicYear: derivedAcademicYear,
194	    startDate,
195	    endDate,
196	    label,
197	    fullLabel,
198	    shortDateSpan,
199	    calendarYear: calendarYearForMonth,
200	    dateSpanVi: shortDateSpan,
201	  };
202	}
