204	/**
205	 * Returns the academic year string "YYYY-(YYYY+1)" for any given date.
206	 * Academic year cut-off is 25/08:
207	 * - Dates on or after 25/08 belong to currentYear - (currentYear + 1)
208	 * - Dates on or before 24/08 belong to (currentYear - 1) - currentYear
209	 */
210	export function getAcademicYear(dateInput: unknown): string {
211	  const parts = parseDateParts(dateInput);
212	  if (!parts) {
213	    return "2026-2027";
214	  }
215	  const { year, month, day } = parts;
216	  if (month > 8 || (month === 8 && day >= 25)) {
217	    return `${year}-${year + 1}`;
218	  }
219	  return `${year - 1}-${year}`;
220	}
