223	 * Trả về danh sách các năm học khả dụng (ví dụ: ["2025-2026", "2026-2027", "2027-2028"]).
224	 * Tự động suy biến xung quanh năm học hiện tại theo quy tắc không hardcode.
225	 */
226	export function getAvailableAcademicYears(referenceDateInput?: unknown): string[] {
227	  const ref = referenceDateInput ?? getSystemReferenceDate();
228	  const currentYearStr = getAcademicYear(ref);
229	  const startYear = parseInt(currentYearStr.split("-")[0], 10);
230	  return [
231	    `${startYear - 1}-${startYear}`,
232	    `${startYear}-${startYear + 1}`,
233	    `${startYear + 1}-${startYear + 2}`,
234	  ];
235	}
