237	export interface CalendarDayCell {
238	  date: Date;
239	  dateString: string; // YYYY-MM-DD
240	  dayNumber: number;
241	  isCurrentMonth: boolean;
242	  isToday: boolean;
243	  isWeekend: boolean;
244	  dayOfWeek: number; // 0 (Sun) to 6 (Sat)
245	}
246	
247	/**
248	 * Tạo danh sách các ô ngày lịch theo chu kỳ vận hành học vụ (25 tháng trước đến 24 tháng này).
249	 * Lưới bắt đầu từ Thứ Hai (T2) và kết thúc ở Chủ Nhật (CN).
250	 * Đảm bảo số ô là bội số của 7 (35 hoặc 42 ô).
251	 */
252	export function generateAcademicMonthGrid(period: AcademicMonthPeriod): CalendarDayCell[] {
253	  const sysDate = getSystemReferenceDate();
254	  const [startYear, startMonth, startDay] = period.startDate
255	    .split("-")
256	    .map((s) => parseInt(s, 10));
257	  const [endYear, endMonth, endDay] = period.endDate
258	    .split("-")
259	    .map((s) => parseInt(s, 10));
260	
261	  const startDateObj = new Date(startYear, startMonth - 1, startDay, 12, 0, 0);
262	  const startDayOfWeek = startDateObj.getDay(); // 0 = Sun, 1 = Mon, ..., 6 = Sat
263	  const mondayOffset = (startDayOfWeek + 6) % 7; // Monday-start offset
264	
265	  const grid: CalendarDayCell[] = [];
266	
267	  // 1. Preceding days before startDate (starting from Monday of that week)
268	  for (let i = mondayOffset; i >= 1; i--) {
269	    const prevDate = new Date(startYear, startMonth - 1, startDay - i, 12, 0, 0);
270	    const dateString = `${prevDate.getFullYear()}-${pad(prevDate.getMonth() + 1)}-${pad(prevDate.getDate())}`;
271	    const dayOfWeek = prevDate.getDay();
272	
273	    grid.push({
274	      date: prevDate,
275	      dateString,
276	      dayNumber: prevDate.getDate(),
277	      isCurrentMonth: false,
278	      isToday: dateString === sysDate,
279	      isWeekend: dayOfWeek === 0 || dayOfWeek === 6,
280	      dayOfWeek,
281	    });
282	  }
283	
284	  // 2. Active operational period days (from 25th of prev month to 24th of current month)
285	  const endDateObj = new Date(endYear, endMonth - 1, endDay, 12, 0, 0);
286	  let curr = new Date(startYear, startMonth - 1, startDay, 12, 0, 0);
287	  while (curr <= endDateObj) {
288	    const dateString = `${curr.getFullYear()}-${pad(curr.getMonth() + 1)}-${pad(curr.getDate())}`;
289	    const dayOfWeek = curr.getDay();
290	
291	    grid.push({
292	      date: curr,
293	      dateString,
294	      dayNumber: curr.getDate(),
295	      isCurrentMonth: true,
296	      isToday: dateString === sysDate,
297	      isWeekend: dayOfWeek === 0 || dayOfWeek === 6,
298	      dayOfWeek,
299	    });
300	
301	    curr = new Date(curr.getFullYear(), curr.getMonth(), curr.getDate() + 1, 12, 0, 0);
302	  }
303	
304	  // 3. Trailing days to complete 7-day rows (at least 35 cells, up to 42 cells)
305	  const totalCells = Math.max(35, Math.ceil(grid.length / 7) * 7);
306	  const trailingDaysNeeded = totalCells - grid.length;
307	
308	  for (let d = 1; d <= trailingDaysNeeded; d++) {
309	    const nextDate = new Date(endYear, endMonth - 1, endDay + d, 12, 0, 0);
310	    const dateString = `${nextDate.getFullYear()}-${pad(nextDate.getMonth() + 1)}-${pad(nextDate.getDate())}`;
311	    const dayOfWeek = nextDate.getDay();
312	
313	    grid.push({
314	      date: nextDate,
315	      dateString,
316	      dayNumber: nextDate.getDate(),
317	      isCurrentMonth: false,
318	      isToday: dateString === sysDate,
319	      isWeekend: dayOfWeek === 0 || dayOfWeek === 6,
320	      dayOfWeek,
321	    });
322	  }
323	
324	  return grid;
325	}
