327	/**
328	 * Returns the complete AcademicMonthPeriod for a given date.
329	 */
330	export function getAcademicMonthInfo(dateInput: unknown): AcademicMonthPeriod {
331	  if (typeof dateInput === "number" && dateInput >= 1 && dateInput <= 12) {
332	    return getAcademicMonthPeriod(dateInput);
333	  }
334	  const parts = parseDateParts(dateInput) || {
335	    year: 2026,
336	    month: 9,
337	    day: 1,
338	  };
339	  const { year, month, day } = parts;
340	
341	  let namedMonth: number;
342	  let calendarYearForMonth: number;
343	
344	  if (day >= 25) {
345	    if (month === 12) {
346	      namedMonth = 1;
347	      calendarYearForMonth = year + 1;
348	    } else {
349	      namedMonth = month + 1;
350	      calendarYearForMonth = year;
351	    }
352	  } else {
353	    namedMonth = month;
354	    calendarYearForMonth = year;
355	  }
356	
357	  return buildAcademicMonthPeriod(calendarYearForMonth, namedMonth);
358	}
