360	/**
361	 * Returns all 12 operational academic months for the specified academic year (e.g. "2026-2027").
362	 * Ordered from Month 9 (index 0) to Month 8 (index 11).
363	 */
364	export function getAcademicMonthsForYear(academicYear: string): AcademicMonthPeriod[] {
365	  const parts = academicYear.split("-").map((p) => parseInt(p.trim(), 10));
366	  const startYear = parts[0];
367	  const months: AcademicMonthPeriod[] = [];
368	
369	  // Indices 0 to 3: Months 9, 10, 11, 12 in startYear
370	  for (let m = 9; m <= 12; m++) {
371	    months.push(buildAcademicMonthPeriod(startYear, m, academicYear));
372	  }
373	
374	  // Indices 4 to 11: Months 1, 2, 3, 4, 5, 6, 7, 8 in startYear + 1
375	  for (let m = 1; m <= 8; m++) {
376	    months.push(buildAcademicMonthPeriod(startYear + 1, m, academicYear));
377	  }
378	
379	  return months;
380	}
