400	/**
401	 * Calculates the adjacent academic month period given a delta (+1, -1, etc.).
402	 */
403	export function getAdjacentAcademicMonth(
404	  period: AcademicMonthPeriod,
405	  delta: number
406	): AcademicMonthPeriod {
407	  const startYear = parseInt(period.academicYear.split("-")[0], 10);
408	  const calendarYearForMonth = period.monthNumber >= 9 ? startYear : startYear + 1;
