410	  // Use day 10 to comfortably sit inside the target month
411	  const target = new Date(calendarYearForMonth, period.monthNumber - 1 + delta, 10);
412	  const targetYear = target.getFullYear();
413	  const targetMonth = target.getMonth() + 1;
414	
415	  return buildAcademicMonthPeriod(targetYear, targetMonth);
